<script setup lang="ts">
import { reviewTerm, reviewModelName, reviewLimitation } from '@/utils/reviewPresentation'
import { computed, nextTick, ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import { participationRuns, readableModelFields, sceneTrackRows } from '@/utils/activityAnalysis'
import type { ActivityFrame, ActivityParticipant } from '@/types/lessonReview'
import AppIcon from '@/components/common/AppIcon.vue'
import LessonStudentState from './LessonStudentState.vue'
import { studentStateColor, studentStateName } from '@/utils/studentStates'
import { overallEngagement, engagementSummary } from '@/utils/classEngagement'

const store = useLessonReviewStore()
const heatmapMode = ref<'states' | 'scores'>('states')
const hasVisualReference = computed(() => frames.value.some(frame => frame.visual_reference !== undefined))
const stateHeatmap = computed(() => hasVisualReference.value && heatmapMode.value === 'states')
const stateCodes: Record<string, string> = { read: 'R', write: 'W', lookup: 'HU', turn_head: 'HT', raise_hand: 'HR', stand: 'S', discuss: 'D', head_up: 'P', head_lowered: 'P', hand_near_head: 'P', standing: 'P', unknown: '—' }
function cellLabel(cell: ActivityParticipant | null) { return cell?.student_state?.label || cell?.label || 'unknown' }
function cellText(cell: ActivityParticipant | null) { return stateHeatmap.value ? stateCodes[cellLabel(cell)] || '—' : cell?.score === null || !cell ? '—' : cell.score.toFixed(2) }
function cellTitle(cell: ActivityParticipant | null) { return cell ? `${studentStateName(cellLabel(cell))} · State confidence ${percentage(cell.student_state?.confidence ?? cell.confidence)} · ${stateHeatmap.value ? 'Visible states. Not an engagement score' : `Temporal rule score ${cell.score ?? 'Unknown'}`}` : 'Unobserved' }
const tabs = [{ id: 'overview', label: 'Student states and engagement' }, { id: 'heatmap', label: 'Person heatmap' }, { id: 'frames', label: 'Original frame evidence' }, { id: 'models', label: 'Models and limitations' }] as const
const selectedScene = ref<number | null>(null)
const framePage = ref(0)
const failedImages = ref(new Set<string>())
const analysis = computed(() => store.data?.activity_analysis)
const frames = computed(() => analysis.value?.frames || [])
const currentFrame = computed(() => store.currentActivityFrame)
const currentContexts = computed(() => analysis.value?.context_segments.filter(row => row.start_sec <= store.currentTime && store.currentTime < row.end_sec) || [])
const scenes = computed(() => [...new Set(frames.value.map(frame => frame.scene_id))])
const sceneId = computed(() => selectedScene.value ?? currentFrame.value?.scene_id ?? scenes.value[0])
const sceneFrames = computed(() => frames.value.filter(frame => frame.scene_id === sceneId.value))
const heatmapStart = ref(0)
const trackContainer = ref<HTMLDivElement | null>(null)
const heatmapFrames = computed(() => sceneFrames.value.slice(heatmapStart.value, heatmapStart.value + 100))
const trackRows = computed(() => sceneId.value === undefined ? [] : sceneTrackRows(heatmapFrames.value, sceneId.value))
const sourceFrames = computed(() => frames.value.slice(framePage.value * 12, (framePage.value + 1) * 12))
const overallScores = computed(() => overallEngagement(frames.value))
const classSummary = computed(() => engagementSummary(frames.value, overallScores.value))
const curveFrames = computed(() => frames.value.map((frame, index) => ({ ...frame, participation_index: frame.visual_reference ? overallScores.value[index]!.smoothed_index : frame.participation ? (frame.participation.active_fraction === null ? null : frame.participation.active_fraction * 100) : frame.participation_index })))
const curveRuns = computed(() => participationRuns(curveFrames.value))
const modelFields = computed(() => readableModelFields(analysis.value?.models || {}))
const summaryCoverage = computed(() => analysis.value?.summary.person_observations ? analysis.value.summary.known_observations / analysis.value.summary.person_observations : null)
const behaviors = computed(() => {
  const counts: Record<string, number> = {}
  for (const frame of frames.value) for (const [label, count] of Object.entries(frame.behaviors)) counts[label] = (counts[label] || 0) + count
  return Object.entries(counts).sort((a, b) => b[1] - a[1])
})
const maxBehavior = computed(() => Math.max(1, ...behaviors.value.map(row => row[1])))
const timelineGroups = [
  { id: 'actions', label: 'Model: reading, writing, hand raising', labels: ['read', 'write', 'raise_hand'], color: '#275cc2' },
  { id: 'lookup', label: 'Model: head up', labels: ['lookup'], color: '#5a88d5' },
  { id: 'other', label: 'Model: head turn, standing, discussion', labels: ['turn_head', 'stand', 'discuss'], color: '#8cafe3' },
  { id: 'pose', label: 'Geometric posture', labels: ['head_up', 'head_lowered', 'hand_near_head', 'standing'], color: '#c0d4ee' },
  { id: 'unknown', label: 'Unknown state', labels: ['unknown'], color: '#e3ebf6' },
]
const stateTimelines = computed(() => frames.value.map(frame => {
  const counts = frame.student_state_counts || {}
  const segments = timelineGroups.map(group => ({ ...group, count: group.labels.reduce((n, label) => n + (counts[label] || 0), 0) }))
  return { frame, segments, title: `${formatReviewTime(frame.timestamp_sec)} · ${frame.detected_people} detected people · ${segments.map(group => `${group.label} ${group.count}`).join(' / ')}` }
}))
const names: Record<string, string> = { reading: 'Reading', writing: 'Writing', listening: 'Listening', hand_raising: 'Hand raising', raising_hand: 'Hand raising', raise_hand: 'Hand raising', standing: 'Standing', discussion: 'Discussion', unknown: 'Unknown', looking_forward: 'Facing forward', head_down: 'Head down', sleeping: 'Leaning on desk', using_phone: 'Using a phone', no_people: 'No visible people detected', low_evidence: 'Insufficient behavior evidence', observed: 'Observed' }
const detectorNames: Record<string, string> = { read: 'Reading', write: 'Writing', lookup: 'Head-up cue', turn_head: 'Head-turn cue', stand: 'Standing cue', discuss: 'Discussion cue' }
const name = (label: string) => detectorNames[label] || names[label] || label
const percentage = (value: number | null) => value === null ? 'Unknown' : `${(value * 100).toFixed(1)}%`
const frameCoverage = (frame: ActivityFrame) => !frame.detected_people ? 'Unknown(No usable detections)' : percentage(frame.coverage)
const x = (frame: ActivityFrame) => 44 + frame.timestamp_sec / Math.max(1, store.duration) * 850
const y = (frame: ActivityFrame) => 142 - (frame.participation_index ?? 0) * 1.2
const points = (run: ActivityFrame[]) => run.map(frame => `${x(frame)},${y(frame)}`).join(' ')
const cellStyle = (cell: ActivityParticipant | null) => stateHeatmap.value ? cell && cellLabel(cell) !== 'unknown' ? { backgroundColor: studentStateColor(cellLabel(cell)), color: ['raise_hand', 'discuss', 'stand'].includes(cellLabel(cell)) ? '#fff' : '#173b70' } : {} : cell?.score === null || !cell ? {} : { backgroundColor: `rgba(36, 94, 219, ${.15 + cell.score * .8})`, color: cell.score > .5 ? '#fff' : '#244b85' }
function seekFrame(frame: ActivityFrame) { selectedScene.value = null; store.seek(frame.timestamp_sec) }
function imageFailed(id: string) { failedImages.value = new Set([...failedImages.value, id]) }
watch(() => store.data?.lesson.id, () => { selectedScene.value = null; framePage.value = 0; heatmapStart.value = 0; failedImages.value = new Set() })
watch(sceneId, () => { heatmapStart.value = 0 })
watch([() => currentFrame.value?.id, sceneId], async () => {
  const frame = currentFrame.value
  if (!frame || frame.scene_id !== sceneId.value) return
  const index = sceneFrames.value.findIndex(row => row.id === frame.id)
  if (index < 0) return
  heatmapStart.value = Math.floor(index / 100) * 100
  await nextTick()
  const container = trackContainer.value
  const header = container && [...container.querySelectorAll<HTMLElement>('th[data-frame-id]')].find(el => el.dataset.frameId === frame.id)
  if (container && header) container.scrollLeft += header.getBoundingClientRect().left - container.getBoundingClientRect().left - container.clientWidth / 2
})
</script>

<template>
  <section id="behavior" class="panel lesson-behavior">
    <div class="panel-heading"><div><h2>Student behavior analysis</h2><p>Source video time · Visible person observations · Activity evidence</p></div><span class="tag" :class="{ sand: !analysis }">{{ analysis ? 'Behavior analysis from the same source' : 'Not provided' }}</span></div>
    <div v-if="!analysis" class="behavior-empty"><AppIcon name="chart" :size="30" /><div><strong>No behavior analysis from the same source is available for this lesson</strong><p>No verifiable behavior curve or person tracks are currently available. Unknown intervals remain blank. They cannot be interpreted as zero participation.</p></div></div>
    <template v-else>
      <div class="behavior-body"><div v-if="hasVisualReference" class="dense-method-note"><span>Seven-class model candidates</span><div><strong>Full-frame and tiled detection</strong><p v-if="currentFrame?.detection_review">Currently retained {{ currentFrame.detected_people }} candidate person boxes<span v-if="currentFrame.detection_review.previous_detected_people !== undefined">. Previously {{ currentFrame.detection_review.previous_detected_people }} items</span>. Mirror candidates are excluded according to configuration. The detected count is not class size or recall.</p><p>The seven-class candidates for this lesson have not passed human annotation review. Overall engagement uses the original project weights for seven behaviors. Scoring coverage is shown separately. The result remains a model estimate.</p></div></div>
        <div class="behavior-tabs" role="tablist" aria-label="Behavior analysis view"><button v-for="tab in tabs" :id="`behavior-${tab.id}-tab`" :key="tab.id" role="tab" :aria-selected="store.behaviorView === tab.id" :aria-controls="`behavior-${tab.id}-panel`" :class="{ active: store.behaviorView === tab.id }" @click="store.behaviorView = tab.id">{{ tab.label }}</button></div>
        <div :id="`behavior-${store.behaviorView}-panel`" role="tabpanel" :aria-labelledby="`behavior-${store.behaviorView}-tab`">
        <div v-if="store.behaviorView === 'overview'" class="current-student-panel" data-behavior-panel="overview"><LessonStudentState :frame="currentFrame" /></div>

        <div v-if="store.behaviorView === 'overview' && hasVisualReference" class="behavior-block" data-testid="visible-state-timeline"><div class="block-title"><h3>Visible states over time</h3><small>Per-frame composition · Select to replay</small></div><p class="block-note">Shows model candidates for the currently detected people, Geometric poses and unknown states. Scenes without people remain blank; These proportions do not describe the whole class or psychological engagement.</p><div class="state-timeline" aria-label="Visible state composition over source video time"><button v-for="row in stateTimelines" :key="row.frame.id" :title="row.title" :aria-label="row.title" :class="{ current: row.frame.id === currentFrame?.id, missing: !row.frame.detected_people }" :style="{ width: `${(row.frame.end_sec - row.frame.start_sec) / store.duration * 100}%` }" @click="seekFrame(row.frame)"><i v-for="segment in row.segments" :key="segment.id" :style="{ height: `${row.frame.detected_people ? segment.count / row.frame.detected_people * 100 : 0}%`, background: segment.color }"></i></button></div><div class="state-heatmap-legend"><span v-for="group in timelineGroups" :key="group.id"><i :style="{ background: group.color }"></i>{{ group.label }}</span></div><p class="block-note mono">00:00 <span class="timeline-end">{{ store.durationText }}</span></p></div>

        <div v-if="store.behaviorView === 'overview'" class="behavior-block" data-behavior-panel="overview"><div class="block-title"><h3>{{ hasVisualReference ? 'Overall student engagement trend' : 'Detected participation action fraction' }} <span>{{ hasVisualReference ? 'Original project rules · 0.3 / 0.7 Temporal smoothing' : 'Reading · Writing · Hand raising / %' }}</span></h3><small>Sampling interval {{ analysis.sampling_interval_sec }} s</small></div><p class="block-note">{{ hasVisualReference ? 'Seven behaviors are weighted and adjusted for class dispersion; Retain estimates with low coverage. Only consecutive valid frames in the same scene are connected. Frames without people or valid behaviors remain blank.' : 'Only adjacent samples in the same scene are connected; Blank means unknown.0% Means only that those actions were not detected. Does not mean no one is participating.' }}</p>
          <p v-if="hasVisualReference" class="block-note" data-testid="class-engagement-summary">Lesson average engagement <b>{{ classSummary.average === null ? 'No score available' : `${classSummary.average.toFixed(1)} / 100` }}</b> · Valid scores {{ classSummary.scored_frames }} / {{ classSummary.total_frames }} frames · Weighted by valid frame duration</p>
          <div v-if="frames.length" class="participation-chart"><svg viewBox="0 0 920 176" role="img" aria-label="Visible participation engagement over source video time. Blank means unknown"><g v-for="tick in [0, 50, 100]" :key="tick"><line x1="44" x2="894" :y1="142 - tick * 1.2" :y2="142 - tick * 1.2" class="chart-grid" /><text x="31" :y="146 - tick * 1.2" text-anchor="end">{{ tick }}</text></g><polyline v-for="(run, i) in curveRuns" :key="i" :points="points(run)" class="participation-line" /><g v-for="frame in curveFrames.filter(f => f.participation_index !== null)" :key="frame.id"><circle :cx="x(frame)" :cy="y(frame)" :r="currentFrame?.id === frame.id ? 4 : 2.4" class="participation-dot"><title>{{ formatReviewTime(frame.timestamp_sec) }} · {{ frame.participation_index }} · Scene {{ frame.scene_id }}</title></circle></g><line :x1="44 + store.currentTime / Math.max(1, store.duration) * 850" :x2="44 + store.currentTime / Math.max(1, store.duration) * 850" y1="15" y2="146" class="chart-cursor" /><text x="44" y="168">00:00</text><text x="894" y="168" text-anchor="end">{{ store.durationText }}</text></svg></div>
          <p v-if="!curveRuns.length" class="block-empty">No state cues currently support an engagement estimate; Keep unknown.</p>

        </div>

        <details v-if="store.behaviorView === 'overview'" class="student-diagnostics" data-testid="student-diagnostics"><summary>Technical diagnostics and cumulative observations <span>Sampling, Rule coverage and provenance</span></summary><p class="block-note">Accumulated counts include repeated observations across frames. Does not represent unique student counts. Visible participation engagement is calculated using the current state rules; Original temporal scores remain in the data.</p>        <div v-if="store.behaviorView === 'overview'" class="behavior-stats"><div><span>Sampled frames / Scene</span><strong>{{ analysis.summary.sampled_frames }}<small> / {{ analysis.summary.scene_count }}</small></strong></div><div><span>Visible person observations</span><strong>{{ analysis.summary.person_observations }}</strong><small>Accumulated across frames. Not unique people</small></div><div><span>Rule-score coverage</span><strong>{{ percentage(summaryCoverage) }}</strong><small>{{ analysis.summary.known_observations }} / {{ analysis.summary.person_observations }} observations</small></div></div>          <div class="coverage-timeline" aria-label="Rule-score coverage and time navigation"><span>Rule-score coverage</span><div><button v-for="frame in frames" :key="frame.id" :style="{ left: `${frame.start_sec / store.duration * 100}%`, width: `${Math.max(.15, (frame.end_sec - frame.start_sec) / store.duration * 100)}%`, opacity: frame.detected_people && frame.coverage !== null ? .25 + frame.coverage * .75 : 1 }" :class="{ unknown: !frame.detected_people || frame.coverage === null, current: currentFrame?.id === frame.id }" :title="`${formatReviewTime(frame.timestamp_sec)} · Rule-score coverage ${frameCoverage(frame)}`" :aria-label="`Go to behavior frame ${frame.id} ${formatReviewTime(frame.timestamp_sec)}`" @click="seekFrame(frame)"></button></div></div><details v-if="currentFrame?.participants.length" class="object-details"><summary>Sources for current people, Pose evidence and confidence</summary><ul><li v-for="participant in currentFrame.participants" :key="participant.track_id"><b>{{ participant.track_id }}</b> · {{ participant.student_state ? studentStateName(participant.student_state.label) : name(participant.label) }}<small v-if="participant.student_state">State source {{ reviewTerm(participant.student_state.source) }} · Confidence {{ participant.student_state.confidence === null ? 'Unknown' : percentage(participant.student_state.confidence) }} · {{ participant.student_state.evidence.join('; ') }}</small><small>Original label {{ name(participant.label) }} · Original confidence {{ percentage(participant.confidence) }} · Box {{ participant.bbox.join(', ') }}</small></li></ul></details><p v-if="currentFrame?.participation" class="block-note">Visible participation rule weights: {{ Object.entries(currentFrame.participation.weights).map(([key, value]) => `${studentStateName(key)} ${value}`).join(' / ') }}. People with unknown states are excluded from rule calculations.</p>        <div v-if="store.behaviorView === 'overview'" class="behavior-block" data-behavior-panel="overview"><div class="block-title"><h3>Instantaneous behavior label distribution</h3><small>Label observation counts accumulated across sampled frames. Independent of rule-score availability</small></div><div v-if="behaviors.length" class="behavior-bars"><div v-for="[label, count] in behaviors" :key="label"><span>{{ name(label) }}</span><div><i :style="{ width: `${count / maxBehavior * 100}%` }"></i></div><b>{{ count }}</b></div></div><p v-else class="block-empty">No behavior label counts were provided.</p></div>

</details>

        <div v-if="store.behaviorView === 'heatmap'" class="behavior-block" data-behavior-panel="heatmap"><div class="block-title"><h3>Within-scene person heatmap</h3><label v-if="scenes.length">Scene <select :value="sceneId" aria-label="View people within the scene" @change="selectedScene = Number(($event.target as HTMLSelectElement).value)"><option v-for="scene in scenes" :key="scene" :value="scene">{{ scene }}</option></select></label></div><p class="block-note">{{ stateHeatmap ? 'Each cell shows the current model state. IDs restart in each scene. No identity linkage; Select a cell to replay the original video.' : 'Each cell shows this visible person’s 0–1 Temporal action rule score. Gray indicates no observation or an unknown score; IDs restart in each scene. No identity linkage. Select a cell to replay the original video.' }}</p>
          <div v-if="hasVisualReference" class="heatmap-mode" aria-label="Heatmap interpretation mode"><button :class="{ active: stateHeatmap }" :aria-pressed="stateHeatmap" @click="heatmapMode = 'states'">Visible states</button><button :class="{ active: !stateHeatmap }" :aria-pressed="!stateHeatmap" @click="heatmapMode = 'scores'">Temporal action score</button></div><p v-if="stateHeatmap" class="block-note">R, W, HU, HT, HR, S, D indicate model classes in this frame; P indicates geometric posture. Gray means unknown. Colors distinguish states. They do not represent psychological engagement.</p><div v-if="trackRows.length" ref="trackContainer" class="track-scroll"><table class="track-table"><thead><tr><th>Visible people</th><th v-for="frame in heatmapFrames" :key="frame.id" :data-frame-id="frame.id"><button :title="frame.id" @click="seekFrame(frame)">{{ formatReviewTime(frame.timestamp_sec) }}</button></th></tr></thead><tbody><tr v-for="track in trackRows" :key="`${sceneId}-${track.track_id}`"><th>{{ track.track_id }}</th><td v-for="(cell, index) in track.cells" :key="heatmapFrames[index]!.id"><button :style="cellStyle(cell)" :class="{ unknown: !cell || (stateHeatmap ? cellLabel(cell) === 'unknown' : cell.score === null) }" :aria-label="`${track.track_id} ${formatReviewTime(heatmapFrames[index]!.timestamp_sec)} ${cellTitle(cell)}`" :title="cellTitle(cell)" @click="seekFrame(heatmapFrames[index]!)">{{ cellText(cell) }}</button></td></tr></tbody></table></div><p v-else class="block-empty">No person tracks are available in the current scene.</p>
          <div v-if="sceneFrames.length > 100" class="page-controls"><span>Showing {{ heatmapStart + 1 }}–{{ Math.min(heatmapStart + 100, sceneFrames.length) }} / {{ sceneFrames.length }} frames</span><button class="btn" :disabled="heatmapStart === 0" @click="heatmapStart = Math.max(0, heatmapStart - 100)">Previous segment</button><button class="btn" :disabled="heatmapStart + 100 >= sceneFrames.length" @click="heatmapStart += 100">Next segment</button></div>
        </div>

        <div v-if="store.behaviorView === 'models'" class="behavior-block" data-behavior-panel="models"><div class="block-title"><h3>Lesson context prediction</h3><small>Classifier probability · Interpreted separately from behavior rule scores</small></div><p v-if="!currentContexts.length" class="block-empty">No trained context model prediction is available at this time.</p><div v-for="context in currentContexts" :key="context.id" class="context-card"><button class="context-time mono" @click="store.seek(context.start_sec)">{{ formatReviewTime(context.start_sec) }}–{{ formatReviewTime(context.end_sec) }}</button><p>{{ context.text }}</p><div class="behavior-pills"><span v-for="label in context.labels" :key="label.label">{{ label.name }} <b>{{ percentage(label.probability) }}</b></span></div><small>{{ reviewModelName(context.model_id) }} · {{ reviewTerm(context.method) }} · {{ context.id }}</small></div><details v-if="analysis.context_segments.length" class="context-list"><summary>View all {{ analysis.context_segments.length }} context records</summary><button v-for="context in analysis.context_segments" :key="context.id" @click="store.seek(context.start_sec)"><span class="mono">{{ formatReviewTime(context.start_sec) }}–{{ formatReviewTime(context.end_sec) }}</span><span>{{ context.text }}</span></button></details></div>

        <div v-if="store.behaviorView === 'frames'" class="behavior-block" data-behavior-panel="frames"><div class="block-title"><h3>Original frame evidence</h3><small>Select to return to the sampled time in the original video</small></div><div v-if="sourceFrames.length" class="source-grid"><button v-for="frame in sourceFrames" :key="frame.id" class="source-frame" :class="{ selected: frame.id === currentFrame?.id }" @click="seekFrame(frame)"><div class="source-image"><img v-if="frame.image_url && !failedImages.has(frame.id)" :src="frame.image_url" :alt="`Original video ${formatReviewTime(frame.timestamp_sec)} Scene ${frame.scene_id}`" loading="lazy" @error="imageFailed(frame.id)" /><span v-else>Source frame: {{ frame.image_url ? 'Unavailable' : 'Not provided' }}</span><span class="source-time mono">{{ formatReviewTime(frame.timestamp_sec) }}</span></div><strong>{{ frame.id }} · Scene {{ frame.scene_id }}{{ frame.scene_cut ? '(Switch)' : '' }}</strong><small>{{ name(frame.status) }} · Rule-score coverage {{ frameCoverage(frame) }}</small></button></div><p v-else class="block-empty">No sampled images or behavior frames were provided.</p><div v-if="frames.length > 12" class="page-controls"><span>Page {{ framePage + 1 }} / {{ Math.ceil(frames.length / 12) }}</span><button class="btn" :disabled="framePage === 0" @click="framePage--">Previous page</button><button class="btn" :disabled="(framePage + 1) * 12 >= frames.length" @click="framePage++">Next page</button></div></div>

        <details v-if="store.behaviorView === 'frames'" class="behavior-evidence"><summary>Behavior text evidence · {{ analysis.evidence.length }} items</summary><button v-for="evidence in analysis.evidence" :key="evidence.id" @click="store.jumpToEvidence(evidence.id)"><span>{{ evidence.id }} · {{ formatReviewTime(evidence.start_sec) }}–{{ formatReviewTime(evidence.end_sec) }}</span><p>{{ evidence.text }}</p></button><p v-if="!analysis.evidence.length">No behavior text is available for Q&A citations.</p></details>
        <details v-if="store.behaviorView === 'models'" open class="behavior-provenance"><summary>Model provenance, Training metrics and scope</summary><p>Same Source SHA-256: <span class="mono">{{ analysis.source_sha256 }}</span></p><p>The records below show only fields actually provided; Offline training evaluations are not independent validation on this video.</p><dl v-if="modelFields.length"><template v-for="(field, index) in modelFields" :key="index"><dt>{{ field.label }}</dt><dd>{{ field.value }}</dd></template></dl><p v-else>No displayable model or training records were provided.</p></details>
        <div v-if="store.behaviorView === 'models'" class="behavior-limits"><h3>Limitations</h3><ul><li>Rule-score coverage is the count of observations with usable rule scores / Detected person count; Coverage is unknown when no people are detected. Instantaneous behavior labels may be available. Short clips or scene changes may still leave rule scores unknown.</li><li>Rule participation index, Behavior confidence and context classification probability are interpreted separately; None directly establishes teaching effectiveness.</li><li v-for="limit in analysis.limitations" :key="limit">{{ reviewLimitation(limit) }}</li></ul></div>
        </div>
      </div>
    </template>
  </section>
</template>

